import{_ as t,o as d,c as o,a2 as c}from"./chunks/framework.brrhTSPk.js";const p=JSON.parse('{"title":"API Reference","description":"","frontmatter":{},"headers":[],"relativePath":"guide/api-reference.md","filePath":"guide/api-reference.md","lastUpdated":1785072736000}'),r={name:"guide/api-reference.md"};function a(n,e,l,i,s,u){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="api-reference" tabindex="-1">API Reference <a class="header-anchor" href="#api-reference" aria-label="Permalink to &quot;API Reference&quot;">​</a></h1><p>Complete signatures for every public type, current as of <strong>0.4.0</strong>. For prose and examples, follow the per-module guides; this page is the quick lookup.</p><h2 id="option-lt-t-gt" tabindex="-1">Option&lt;T&gt; <a class="header-anchor" href="#option-lt-t-gt" aria-label="Permalink to &quot;Option&amp;lt;T&amp;gt;&quot;">​</a></h2><p><code>Maybe\\Option\\Option</code> — an optional value, either <code>Some</code> or <code>None</code>.</p><table tabindex="0"><thead><tr><th>Member</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>Option::some</code></td><td><code>some($value): Option&lt;T&gt;</code></td><td>Wrap a present value (never <code>null</code>).</td></tr><tr><td><code>Option::none</code></td><td><code>none(): Option&lt;mixed&gt;</code></td><td>The empty option.</td></tr><tr><td><code>Option::fromNullable</code></td><td><code>fromNullable($value): Option&lt;T&gt;</code></td><td><code>null</code> → <code>None</code>, otherwise <code>Some</code>.</td></tr><tr><td><code>map</code></td><td><code>map(callable $fn): Option</code></td><td>Transform the value; a <code>null</code> result collapses to <code>None</code>.</td></tr><tr><td><code>flatMap</code></td><td><code>flatMap(callable $fn): Option</code></td><td>Chain an operation returning an <code>Option</code>.</td></tr><tr><td><code>filter</code></td><td><code>filter(callable $predicate): Option</code></td><td>Keep the value only if the predicate holds.</td></tr><tr><td><code>match</code></td><td><code>match(callable $onSome, callable $onNone)</code></td><td>Handle both branches, returns their result.</td></tr><tr><td><code>unwrap</code></td><td><code>unwrap()</code></td><td>The value, or throws <code>UnwrapNoneException</code> on <code>None</code>.</td></tr><tr><td><code>unwrapOr</code></td><td><code>unwrapOr($default)</code></td><td>The value, or an eager fallback.</td></tr><tr><td><code>unwrapOrElse</code></td><td><code>unwrapOrElse(callable $fn)</code></td><td>The value, or a lazy fallback.</td></tr><tr><td><code>expect</code></td><td><code>expect(string $message)</code></td><td>The value, or throws with your message.</td></tr><tr><td><code>okOr</code></td><td><code>okOr($error): Result</code></td><td><code>Some</code>→<code>Ok</code>, <code>None</code>→<code>Err($error)</code>.</td></tr><tr><td><code>okOrElse</code></td><td><code>okOrElse(callable $fn): Result</code></td><td>Like <code>okOr</code>, error computed lazily.</td></tr><tr><td><code>isSome</code> / <code>isNone</code></td><td><code>(): bool</code></td><td>Inspect the variant.</td></tr></tbody></table><h2 id="result-lt-t-e-gt" tabindex="-1">Result&lt;T, E&gt; <a class="header-anchor" href="#result-lt-t-e-gt" aria-label="Permalink to &quot;Result&amp;lt;T, E&amp;gt;&quot;">​</a></h2><p><code>Maybe\\Result\\Result</code> — a success (<code>Ok</code>) or a typed failure (<code>Err</code>).</p><table tabindex="0"><thead><tr><th>Member</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>Result::ok</code></td><td><code>ok($value): Result&lt;T,mixed&gt;</code></td><td>A success.</td></tr><tr><td><code>Result::err</code></td><td><code>err($error): Result&lt;mixed,E&gt;</code></td><td>A typed failure.</td></tr><tr><td><code>map</code></td><td><code>map(callable $fn): Result</code></td><td>Transform the success value.</td></tr><tr><td><code>mapErr</code></td><td><code>mapErr(callable $fn): Result</code></td><td>Transform the error value.</td></tr><tr><td><code>andThen</code></td><td><code>andThen(callable $fn): Result</code></td><td>Chain a fallible op; short-circuits on <code>Err</code>.</td></tr><tr><td><code>orElse</code></td><td><code>orElse(callable $fn): Result</code></td><td>Recover from <code>Err</code>; passes <code>Ok</code> through.</td></tr><tr><td><code>match</code></td><td><code>match(callable $onOk, callable $onErr)</code></td><td>Handle both branches.</td></tr><tr><td><code>unwrap</code></td><td><code>unwrap()</code></td><td>The value, or throws <code>UnwrapErrException</code> on <code>Err</code>.</td></tr><tr><td><code>unwrapErr</code></td><td><code>unwrapErr()</code></td><td>The error, or throws <code>UnwrapOkException</code> on <code>Ok</code>.</td></tr><tr><td><code>unwrapOr</code></td><td><code>unwrapOr($default)</code></td><td>The value, or an eager fallback.</td></tr><tr><td><code>unwrapOrElse</code></td><td><code>unwrapOrElse(callable $fn)</code></td><td>The value, or a fallback computed from the error.</td></tr><tr><td><code>expect</code></td><td><code>expect(string $message)</code></td><td>The value, or throws with your message.</td></tr><tr><td><code>okOption</code></td><td><code>okOption(): Option</code></td><td><code>Ok(v)</code>→<code>Some(v)</code>, <code>Err</code>→<code>None</code>.</td></tr><tr><td><code>errOption</code></td><td><code>errOption(): Option</code></td><td><code>Err(e)</code>→<code>Some(e)</code>, <code>Ok</code>→<code>None</code>.</td></tr><tr><td><code>isOk</code> / <code>isErr</code></td><td><code>(): bool</code></td><td>Inspect the variant.</td></tr></tbody></table><h2 id="schema" tabindex="-1">Schema <a class="header-anchor" href="#schema" aria-label="Permalink to &quot;Schema&quot;">​</a></h2><p><code>Maybe\\Schema\\Schema</code> — builders for immutable validators. Every modifier returns a new instance.</p><table tabindex="0"><thead><tr><th>Builder</th><th>Signature</th></tr></thead><tbody><tr><td><code>Schema::string</code></td><td><code>string(): StringSchema</code></td></tr><tr><td><code>Schema::int</code></td><td><code>int(): IntSchema</code></td></tr><tr><td><code>Schema::bool</code></td><td><code>bool(): BoolSchema</code></td></tr><tr><td><code>Schema::date</code></td><td><code>date(): DateSchema</code></td></tr><tr><td><code>Schema::enumeration</code></td><td><code>enumeration(array $allowedValues): EnumSchema</code></td></tr><tr><td><code>Schema::arrayOf</code></td><td><code>arrayOf(SchemaInterface $itemSchema): ArraySchema</code></td></tr><tr><td><code>Schema::shape</code></td><td><code>shape(array $shape): ObjectSchema</code></td></tr><tr><td><code>Schema::option</code></td><td><code>option(SchemaInterface $inner): OptionSchema</code></td></tr></tbody></table><p><strong>Modifiers:</strong> <code>StringSchema</code>: <code>-&gt;trimmed()</code>, <code>-&gt;min(int)</code>, <code>-&gt;max(int)</code>, <code>-&gt;regex(string)</code>. <code>IntSchema</code>: <code>-&gt;min(int)</code>, <code>-&gt;max(int)</code>. <code>DateSchema</code>: <code>-&gt;format(string)</code>, <code>-&gt;min(DateTimeImmutable)</code>, <code>-&gt;max(DateTimeImmutable)</code>. <code>ObjectSchema</code>: <code>-&gt;allowUnknown()</code>.</p><p><strong>Entry points (all schemas):</strong> <code>-&gt;safeParse($input): Result&lt;T, ValidationErrorBag&gt;</code> (never throws) and <code>-&gt;parse($input): T</code> (throws <code>ValidationException</code>). <code>-&gt;transform(callable): SchemaInterface</code>.</p><h2 id="validation-errors-0-4-0" tabindex="-1">Validation errors (0.4.0) <a class="header-anchor" href="#validation-errors-0-4-0" aria-label="Permalink to &quot;Validation errors (0.4.0)&quot;">​</a></h2><p>Tell-Don&#39;t-Ask value objects — there are <strong>no</strong> <code>path()</code>, <code>message()</code>, <code>code()</code>, <code>all()</code>, or <code>first()</code> getters.</p><p><code>Maybe\\Schema\\ValidationErrorBag</code> — a first-class collection, <code>Countable</code> and iterable.</p><table tabindex="0"><thead><tr><th>Member</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>count</code></td><td><code>count(): int</code></td><td>Number of errors (<code>Countable</code>).</td></tr><tr><td><code>isEmpty</code></td><td><code>isEmpty(): bool</code></td><td>Whether there are no errors.</td></tr><tr><td>iteration</td><td><code>foreach ($bag as $error)</code></td><td>Yields <code>ValidationError</code> items.</td></tr><tr><td><code>describe</code></td><td><code>describe(): string[]</code></td><td>One <code>&quot;path: message&quot;</code> line per error.</td></tr><tr><td><code>summary</code></td><td><code>summary(): string</code></td><td>First line plus &quot;(and N more…)&quot;.</td></tr><tr><td><code>toArray</code></td><td><code>toArray(): array[]</code></td><td>Serialization boundary: <code>[&#39;path&#39;,&#39;message&#39;,&#39;code&#39;]</code> rows.</td></tr><tr><td><code>withError</code> / <code>merge</code></td><td><code>(...): self</code></td><td>Immutable add / combine.</td></tr></tbody></table><p><code>Maybe\\Schema\\ValidationError</code>: <code>describedAs(): string</code>, <code>underField(string): self</code>, <code>underIndex(int): self</code>, <code>toArray(): array{path,message,code}</code>. Build one with a <code>Path</code>: <code>new ValidationError(Path::field(&#39;email&#39;), &#39;message&#39;, &#39;code&#39;)</code>.</p><p><code>Maybe\\Schema\\Path</code>: <code>Path::root(): self</code>, <code>Path::field(string): self</code>, <code>-&gt;underField(string): self</code>, <code>-&gt;underIndex(int): self</code>, <code>-&gt;toString(): string</code>.</p><h2 id="dto" tabindex="-1">DTO <a class="header-anchor" href="#dto" aria-label="Permalink to &quot;DTO&quot;">​</a></h2><p><code>Maybe\\DTO\\DTO</code> — abstract base mapping validated input into a typed object.</p><table tabindex="0"><thead><tr><th>Member</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>schema</code></td><td><code>abstract static schema(): ObjectSchema</code></td><td>Define the shape.</td></tr><tr><td><code>fromValidated</code></td><td><code>abstract static protected fromValidated(array): static</code></td><td>Build the instance from validated data.</td></tr><tr><td><code>fromArray</code></td><td><code>static fromArray(array $input): Result&lt;static, ValidationErrorBag&gt;</code></td><td>Validate, never throws.</td></tr><tr><td><code>parse</code></td><td><code>static parse(array $input): static</code></td><td>Validate, throws on invalid input.</td></tr></tbody></table><h2 id="async" tabindex="-1">Async <a class="header-anchor" href="#async" aria-label="Permalink to &quot;Async&quot;">​</a></h2><p><code>Maybe\\Async\\Async</code> and <code>AsyncFuture</code> — concurrency via child processes (<code>proc_open</code>).</p><table tabindex="0"><thead><tr><th>Member</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>async</code></td><td><code>async(callable $task, array $args = [], array $options = []): AsyncFuture</code></td><td>Start a task. <code>options: [&#39;timeout&#39; =&gt; 2.5]</code>. Wraps <code>Async::run</code>.</td></tr><tr><td><code>await</code></td><td><code>await($futureOrArray)</code></td><td>Resolve one future, or an array via <code>Async::all</code>.</td></tr><tr><td><code>Async::run</code></td><td><code>run(callable $task, array $args = [], array $options = []): AsyncFuture</code></td><td>Same as <code>async()</code>, called directly on the class.</td></tr><tr><td><code>Async::all</code></td><td><code>all(array $futures): array</code></td><td>Wait for all (keys preserved).</td></tr><tr><td><code>Async::race</code></td><td><code>race(array $futures)</code></td><td>First to finish wins.</td></tr><tr><td><code>Async::pool</code></td><td><code>pool(array $tasks, int $limit = 5, array $options = []): array</code></td><td>Bounded concurrency.</td></tr><tr><td><code>Async::setDefaultTempDir</code></td><td><code>setDefaultTempDir(string $tempDir): void</code></td><td>Override where worker temp files are written.</td></tr><tr><td><code>Async::setDefaultTimeout</code></td><td><code>setDefaultTimeout(?float $seconds): void</code></td><td>Default per-task timeout when <code>options[&#39;timeout&#39;]</code> is omitted.</td></tr><tr><td><code>Async::setDefaultPollInterval</code></td><td><code>setDefaultPollInterval(int $microseconds): void</code></td><td>Default polling interval used while waiting on a future.</td></tr><tr><td><code>Async::setDefaultMaxInputBytes</code></td><td><code>setDefaultMaxInputBytes(?int $bytes): void</code></td><td>Default serialized input limit; <code>null</code> disables it.</td></tr><tr><td><code>Async::setDefaultMaxOutputBytes</code></td><td><code>setDefaultMaxOutputBytes(?int $bytes): void</code></td><td>Default serialized output limit; <code>null</code> disables it.</td></tr><tr><td><code>AsyncFuture</code></td><td><code>-&gt;then(fn)</code>, <code>-&gt;catch(fn)</code>, <code>-&gt;finally(fn)</code></td><td>Register callbacks.</td></tr><tr><td></td><td><code>-&gt;resolve()</code></td><td>Block until done (or timeout).</td></tr><tr><td></td><td><code>-&gt;pending(): bool</code>, <code>-&gt;cancel()</code></td><td>Non-blocking check / kill the process.</td></tr></tbody></table><p>Async size options are <code>max_input_bytes</code> (16 MiB by default), <code>max_output_bytes</code> (64 MiB by default), and <code>include_remote_trace</code> (disabled by default). A size limit can be set to <code>null</code> for a trusted, explicitly bounded workload.</p><p><code>Maybe\\Async\\Exception\\PayloadTooLargeException</code> reports which IPC direction exceeded its configured limit. <code>TaskFailedException::remoteTrace()</code> is empty by default; enable <code>include_remote_trace</code> only in trusted diagnostics.</p><h2 id="global-helper-functions" tabindex="-1">Global helper functions <a class="header-anchor" href="#global-helper-functions" aria-label="Permalink to &quot;Global helper functions&quot;">​</a></h2><p>Auto-loaded (namespace <code>Maybe\\</code>): <code>some()</code>, <code>none()</code>, <code>fromNullable()</code>, <code>ok()</code>, <code>err()</code>, <code>stringSchema()</code>, <code>intSchema()</code>, <code>boolSchema()</code>, <code>dateSchema()</code>, <code>enumSchema()</code>, <code>arraySchema()</code>, <code>objectSchema()</code>, <code>optionSchema()</code>, <code>async()</code>, <code>await()</code>.</p><blockquote><p>Writing code with an AI assistant? Point it at <a href="/maybe/llms.txt"><code>llms.txt</code></a> for the same signatures in an LLM-friendly form.</p></blockquote>',30)])])}const m=t(r,[["render",a]]);export{p as __pageData,m as default};
